import { chromium } from "<project>/flare/node_modules/playwright-core/index.mjs";
export const D="<tmp>/904c52d9-f200-4552-8ce5-05e400952efa/scratchpad/fresh5";
export async function start(desktop=false){
 const b=await chromium.launch({channel:"chrome"});
 const opts=desktop?{viewport:{width:1280,height:800}}:{viewport:{width:390,height:844},isMobile:true,hasTouch:true};
 const c=await b.newContext({...opts,geolocation:{latitude:42.3196,longitude:-83.2129},permissions:["geolocation"]});
 const p=await c.newPage();
 p.on("console",m=>{if(m.type()==="error"||m.type()==="warning")console.log("CONSOLE",m.type(),m.text().slice(0,200))});
 p.on("pageerror",e=>console.log("PAGEERROR",e.message));
 p.on("request",r=>{const u=r.url(); if(!u.includes("flare-outside.onrender.com")&&!u.startsWith("data:")&&!u.startsWith("blob:"))console.log("EXTREQ",u.slice(0,120))});
 return {b,c,p};
}
export async function dump(p,label){
 const txt=await p.evaluate(()=>document.body.innerText);
 console.log("=== "+label+" url="+p.url()+"\n"+txt.slice(0,2500));
 const els=await p.$$eval("a,button,input,select,textarea,[role=button],[role=radio],[role=switch],label",els=>els.filter(e=>{const r=e.getBoundingClientRect();return r.width>0&&r.height>0}).map(e=>`${e.tagName}${e.type?"["+e.type+"]":""} "${(e.innerText||e.getAttribute("aria-label")||e.value||e.name||"").trim().replace(/\s+/g," ").slice(0,50)}" ${Math.round(e.getBoundingClientRect().width)}x${Math.round(e.getBoundingClientRect().height)}`));
 console.log("--els\n"+els.join("\n"));
}
export async function shot(p,n){await p.screenshot({path:`${D}/${n}.png`});}
EOF
cat > $D/s3.mjs <<'EOF'
import {start,dump,shot} from "./lib.mjs";
const {b,p}=await start();
await p.goto("https://flare-outside.onrender.com/",{waitUntil:"networkidle"});
await p.getByRole("link",{name:"Try a demo"}).first().tap();
await p.waitForLoadState("networkidle"); await p.waitForTimeout(1500);
await shot(p,"d01-demo-start"); await dump(p,"demo start");
await b.close();
EOF
cd $D && node s3.mjs

